import { CdkTextareaAutosize } from '@angular/cdk/text-field';
import {
  ChangeDetectionStrategy,
  Component,
  Directive,
  ElementRef,
  Provider,
  booleanAttribute,
  computed,
  forwardRef,
  inject,
  input,
  model,
  output,
  signal,
} from '@angular/core';
import { NG_VALUE_ACCESSOR } from '@angular/forms';
import { CsButtonDirective } from '../core/foundations/cs-button.directive';
import { CsControlBase } from '../core/platform/cs-control-base.class';
import { CsIdService } from '../core/platform/cs-id.service';
import { CsLocalizationService } from '../core/platform/cs-localization.service';
import { valueAccessor } from '../core/forms/value-accessor.function';

@Component({
  changeDetection: ChangeDetectionStrategy.OnPush,
  selector: 'cs-switch',
  providers: [valueAccessor(() => SwitchComponent)],
  templateUrl: './switch.component.html',
  styleUrl: './switch.component.scss',
})
export class SwitchComponent extends CsControlBase<boolean> {
  protected toggle(): void {
    this.updateValue(!this.value());
  }
}

scss:
button {
  display: inline-flex;
  align-items: center;
  gap: var(--cs-space-2);
  min-block-size: 2.75rem;
  padding: 0;
  border: 0;
  background: transparent;
  color: inherit;
}
.track {
  display: block;
  inline-size: 2.75rem;
  block-size: 1.55rem;
  padding: 2px;
  border: 1px solid var(--cs-border-strong);
  border-radius: 999px;
  background: var(--cs-surface);
}
.track::before {
  content: '';
  display: block;
  inline-size: 1.15rem;
  aspect-ratio: 1;
  border-radius: 50%;
  background: var(--cs-ink);
  transition: transform var(--cs-duration);
}
button[aria-checked='true'] .track {
  background: var(--cs-lime);
}
button[aria-checked='true'] .track::before {
  transform: translateX(1.15rem);
}
